import{read,write,record,shuffle,escape as e,turma}from'./storage.js';
let promise;
export const bank=()=>promise??=(fetch(new URL('./questions.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Banco indisponível');return r.json()}).catch(err=>{promise=null;throw err}));
export async function study(root,mode,subject='Matemática',topic=''){
root.innerHTML='<div class="empty">Preparando seu estudo…</div>';let questions;try{questions=await bank()}catch{root.innerHTML='<div class="empty">Não foi possível carregar as questões. Verifique sua conexão e atualize a página.</div>';return}if(!root.isConnected)return;
const names=[...new Set(questions.map(q=>q.subject))];if(!names.includes(subject))subject=names[0];let deck=[],index=0,score=0,revealed=false;
root.innerHTML=`<div class="quiz-shell"><div class="quiz-selects"><label class="field">Matéria<select id="studySubject">${names.map(n=>`<option ${n===subject?'selected':''}>${e(n)}</option>`).join('')}</select></label><label class="field">Assunto<select id="studyTopic"></select></label><button class="button" id="startStudy">${mode==='quiz'?'Começar rodada':'Estudar cartões'} →</button></div><div id="studyStage" class="panel"></div></div>`;
const sub=root.querySelector('#studySubject'),topics=root.querySelector('#studyTopic'),stage=root.querySelector('#studyStage');
function populate(){const list=[...new Set(questions.filter(q=>q.subject===sub.value).map(q=>q.topic))];topics.innerHTML='<option value="">Todos os assuntos</option>'+list.map(t=>`<option ${t===topic?'selected':''}>${e(t)}</option>`).join('')}
function start(){const pool=questions.filter(q=>q.subject===sub.value&&(!topics.value||q.topic===topics.value));const seen=read('missao-seen-'+turma(),[]);deck=shuffle(pool.filter(q=>!seen.includes(q.question)));if(!deck.length){deck=shuffle(pool);write('missao-seen-'+turma(),seen.filter(s=>!pool.some(q=>q.question===s)))}if(mode==='flash'){const reviews=read('missao-card-reviews-'+turma(),{});deck=shuffle(pool).sort((a,b)=>(reviews[a.question]?.next||0)-(reviews[b.question]?.next||0))}deck=deck.slice(0,mode==='quiz'?10:20);index=0;score=0;render()}
function render(){if(index>=deck.length){stage.innerHTML=`<div class="empty"><span style="font-size:40px">✦</span><h2>Mais um passo no seu aprendizado!</h2><p>${mode==='quiz'?`${score} de ${deck.length} respostas corretas.`:`Você revisou ${deck.length} cartões.`}</p><div class="button-row"><button class="button" id="again">Continuar praticando</button><a class="button secondary" href="#home">Voltar ao painel</a></div></div>`;stage.querySelector('#again').onclick=start;return}const q=deck[index];revealed=false;
stage.innerHTML=`<div class="question-top"><span>${e(q.topic)}</span><span>${index+1} de ${deck.length}</span></div><div class="progress-track"><i style="width:${index/deck.length*100}%"></i></div>`;
if(mode==='flash'){stage.innerHTML+=`<button class="flash-card" id="flip"><small>LEMBRE ANTES DE REVELAR</small>${e(q.question)}</button><div id="flashActions" class="button-row"><button class="button" id="reveal">Revelar resposta ↻</button></div>`;
const flip=()=>{if(revealed)return;revealed=true;stage.querySelector('#flip').innerHTML=`<small>RESPOSTA E EXPLICAÇÃO</small>${e(q.answer)}<p style="font-size:14px;margin-top:20px">${e(q.explanation)}</p>`;stage.querySelector('#flashActions').innerHTML='<button class="button secondary" data-rating="again">Rever depois</button><button class="button" data-rating="good">Lembrei bem ✓</button>';stage.querySelectorAll('[data-rating]').forEach(b=>b.onclick=()=>{const reviews=read('missao-card-reviews-'+turma(),{});reviews[q.question]={next:Date.now()+(b.dataset.rating==='good'?86400000*3:600000),rating:b.dataset.rating};write('missao-card-reviews-'+turma(),reviews);index++;render()})};stage.querySelector('#flip').onclick=flip;stage.querySelector('#reveal').onclick=flip;
}else{stage.innerHTML+=`<h2 class="question-title">${e(q.question)}</h2><div class="options">${shuffle(q.options).map((o,i)=>`<button class="option"><b>${'ABCD'[i]}</b><span>${e(o)}</span></button>`).join('')}</div><div id="answerFeedback" aria-live="polite"></div>`;stage.querySelectorAll('.option').forEach(b=>b.onclick=()=>{const right=b.querySelector('span').textContent===q.answer;if(right)score++;record(q,right);const seen=read('missao-seen-'+turma(),[]);write('missao-seen-'+turma(),[...new Set([...seen,q.question])]);stage.querySelectorAll('.option').forEach(o=>{o.disabled=true;if(o.querySelector('span').textContent===q.answer)o.classList.add('good')});if(!right)b.classList.add('wrong');stage.querySelector('#answerFeedback').innerHTML=`<div class="feedback"><strong>${right?'Muito bem! Resposta correta.':'Vamos entender essa resposta.'}</strong><p>${e(q.explanation)}</p></div><button class="button" id="nextQuestion">${index===deck.length-1?'Ver resultado':'Próxima questão'} →</button>`;stage.querySelector('#nextQuestion').onclick=()=>{index++;render()}})}}
populate();sub.onchange=populate;root.querySelector('#startStudy').onclick=start;start();}
